<script setup lang="ts">
import { ArrowLeft, ArrowRight, CalendarRange } from '@lucide/vue'
import { fromZonedTime } from 'date-fns-tz'
import { SALON_TIMEZONE,formatXof } from '~~/shared/constants/business'
definePageMeta({layout:'admin',middleware:'admin'})
const period=ref('week'),selectedDate=ref(new Intl.DateTimeFormat('en-CA',{timeZone:SALON_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())),staffFilter=ref(''),items=ref<Array<{id:string;reference:string;status:string;startsAt:string;customer:{name:string};staffName:string;services:string[];totalXof:number}>>([]),errorMessage=ref('')
function range(){const start=new Date(`${selectedDate.value}T12:00:00`),count=period.value==='day'?1:period.value==='month'?31:7;const end=new Date(start);end.setDate(end.getDate()+count);return{from:fromZonedTime(`${selectedDate.value}T00:00:00`,SALON_TIMEZONE).toISOString(),to:fromZonedTime(`${new Intl.DateTimeFormat('en-CA',{timeZone:SALON_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(end)}T00:00:00`,SALON_TIMEZONE).toISOString()}}
async function load(){errorMessage.value='';try{const result=await $fetch<{appointments:typeof items.value}>('/api/admin/appointments',{query:range()});items.value=result.appointments}catch(error){errorMessage.value=(error as {data?:{statusMessage?:string}})?.data?.statusMessage||'Le calendrier ne peut pas être chargé.'}}
watch([selectedDate,period],load,{immediate:true})
const filtered=computed(()=>items.value.filter((item)=>!staffFilter.value||item.staffName===staffFilter.value))
const professionals=computed(()=>[...new Set(items.value.map((item)=>item.staffName).filter(Boolean))])
const dayGroups=computed(()=>{const map=new Map<string,typeof filtered.value>();for(const item of filtered.value){const key=new Intl.DateTimeFormat('en-CA',{timeZone:SALON_TIMEZONE}).format(new Date(item.startsAt));map.set(key,[...(map.get(key)||[]),item])}return[...map].sort(([a],[b])=>a.localeCompare(b))})
function dateLabel(day:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,dateStyle:'full'}).format(new Date(`${day}T12:00:00Z`))}
function time(value:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,hour:'2-digit',minute:'2-digit'}).format(new Date(value))}
function shift(amount:number){const date=new Date(`${selectedDate.value}T12:00:00`);date.setDate(date.getDate()+amount);selectedDate.value=new Intl.DateTimeFormat('en-CA',{timeZone:SALON_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
useSeoMeta({title:'Calendrier — Administration',robots:'noindex,nofollow'})
</script>
<template><div><div class="admin-page-head"><div><span class="section-kicker">Planning de l’équipe</span><h1>Le calendrier.</h1><p>Créneaux déjà réservés, affichés dans le fuseau Africa/Porto-Novo.</p></div><NuxtLink class="btn btn-primary" to="/admin/rendez-vous">Gérer les rendez-vous <ArrowRight :size="14"/></NuxtLink></div><p v-if="errorMessage" class="admin-alert">{{errorMessage}}</p><div class="admin-toolbar"><div class="admin-view-tabs"><button v-for="item in ['day','week','month']" :key="item" :class="{'is-active':period===item}" @click="period=item">{{item==='day'?'Jour':item==='week'?'Semaine':'Mois'}}</button></div><input v-model="selectedDate" class="form-control" type="date" aria-label="Date du calendrier"><select v-model="staffFilter" class="form-control"><option value="">Toute l’équipe</option><option v-for="person in professionals" :key="person">{{person}}</option></select><button class="admin-inline-action" @click="shift(period==='day'?1:period==='week'?7:30)">Avancer <ArrowRight :size="13"/></button></div><div class="calendar-groups"><section v-for="[day,events] in dayGroups" :key="day" class="admin-card"><div class="admin-card__title"><h2>{{dateLabel(day)}}</h2><span class="status-pill">{{events.length}} rendez-vous</span></div><article v-for="item in events" :key="item.id" class="calendar-event"><time>{{time(item.startsAt)}}</time><div><strong>{{item.customer.name}}</strong><small>{{item.services.join(' · ')}} · {{item.staffName}}</small></div><span class="status-pill">{{item.status}}</span><span>{{formatXof(item.totalXof)}}</span><NuxtLink :to="'/admin/rendez-vous'">Voir</NuxtLink></article><div v-if="!events.length" class="admin-empty">Aucun rendez-vous prévu.</div></section><div v-if="!dayGroups.length" class="admin-card admin-empty">Aucun rendez-vous dans cette période.</div></div></div></template>
<style scoped>.calendar-groups{display:grid;gap:.8rem}.calendar-event{display:grid;grid-template-columns:70px 1.4fr auto auto auto;align-items:center;gap:.9rem;border-top:1px solid #f0eae4;padding:.85rem 1rem}.calendar-event time{color:#6b2d45;font-size:.72rem;font-weight:700}.calendar-event div{display:grid;gap:.2rem}.calendar-event strong{font-size:.71rem}.calendar-event small{color:#8a7d75;font-size:.61rem}.calendar-event>span:nth-last-child(2){font-size:.66rem}.calendar-event>a{color:#6b2d45;font-size:.63rem}@media(max-width:700px){.calendar-event{grid-template-columns:55px 1fr auto}.calendar-event>span:nth-last-child(2){display:none}}</style>
